// The sensor you own. rtl_433 prints both in every event.
const MODEL = "Fineoffset-WH65B";
const ID = 227;

const e = msg.payload;
if (!e || e.model !== MODEL || Number(e.id) !== ID) return null;

const n = (v) => (v === undefined || v === null || v === "" ? undefined : Number(v));
const wind = n(e.wind_avg_m_s) ?? (n(e.wind_avg_km_h) !== undefined ? n(e.wind_avg_km_h) / 3.6 : undefined);
const gust = n(e.wind_max_m_s) ?? (n(e.wind_max_km_h) !== undefined ? n(e.wind_max_km_h) / 3.6 : undefined);

msg.payload = {
  temperature: n(e.temperature_C),
  humidity: n(e.humidity),
  pressure: n(e.pressure_hPa),
  wind_speed: wind,
  wind_gusts: gust,
  wind_direction: n(e.wind_dir_deg),
  rain_total_mm: n(e.rain_mm),
  light_lux: n(e.light_lux),
  uv: n(e.uvi) ?? n(e.uv),
};
return msg;
